  "/components/Hud.js": "// Default HUD: shows each numeric variable as a small bar.\n// The engineer agent may replace this file; it must keep the same props.\nexport default function Hud({ vars, variables }) {\n  if (!variables || variables.length === 0) return null;\n  return (\n    <div className=\"sg-hud\">\n      {variables.map((v) => {\n        const value = vars[v.id] ?? v.init;\n        const pct = v.max === v.min ? 0 : ((value - v.min) / (v.max - v.min)) * 100;\n        return (\n          <div key={v.id} className=\"sg-hud-item\">\n            <span>{v.label}</span>\n            <span className=\"sg-hud-bar\">\n              <span style={{ width: pct + \"%\" }} />\n            </span>\n            <span className=\"sg-hud-value\">{value}</span>\n          </div>\n        );\n      })}\n    </div>\n  );\n}\n",
  "/engine/Player.js": "import { useEffect, useMemo, useState } from \"react\";\nimport { availableChoices, indexNodes, initState, step } from \"./core\";\n\nconst SAVE_PREFIX = \"story-save:\";\nconst ENDINGS_PREFIX = \"story-endings:\";\n\nfunction load(key, fallback) {\n  try {\n    const raw = window.localStorage.getItem(key);\n    return raw ? JSON.parse(raw) : fallback;\n  } catch {\n    return fallback;\n  }\n}\n\nfunction save(key, value) {\n  try {\n    window.localStorage.setItem(key, JSON.stringify(value));\n  } catch {\n    // storage unavailable (private mode / sandbox): play still works, just no save\n  }\n}\n\nexport default function Player({ story, Hud }) {\n  const nodes = useMemo(() => indexNodes(story), [story]);\n  const chars = useMemo(() => Object.fromEntries(story.characters.map((c) => [c.id, c])), [story]);\n  const saveKey = SAVE_PREFIX + story.meta.title;\n  const endingsKey = ENDINGS_PREFIX + story.meta.title;\n\n  const [state, setState] = useState(() => {\n    const saved = load(saveKey, null);\n    return saved && nodes[saved.nodeId] ? saved : initState(story);\n  });\n  const [lineIndex, setLineIndex] = useState(0);\n  const [endings, setEndings] = useState(() => load(endingsKey, []));\n\n  const node = nodes[state.nodeId];\n  const lines = node ? node.lines : [];\n  const allShown = lineIndex >= lines.length - 1;\n\n  useEffect(() => {\n    save(saveKey, state);\n  }, [saveKey, state]);\n\n  useEffect(() => {\n    if (state.ended && allShown && !endings.includes(state.nodeId)) {\n      const next = [...endings, state.nodeId];\n      setEndings(next);\n      save(endingsKey, next);\n    }\n  }, [state, allShown, endings, endingsKey]);\n\n  if (!node) return <div className=\"sg-error\">剧情数据有误：找不到节点 {state.nodeId}</div>;\n\n  const choose = (index) => {\n    setState(step(story, state, index));\n    setLineIndex(0);\n  };\n  const restart = () => {\n    setState(initState(story));\n    setLineIndex(0);\n  };\n\n  const line = lines[Math.min(lineIndex, lines.length - 1)];\n  const speaker = line.speaker ? chars[line.speaker] : null;\n  const endingNodes = story.nodes.filter((n) => n.type === \"ending\");\n\n  return (\n    <div className=\"sg-root\">\n      <header className=\"sg-header\">\n        <span className=\"sg-title\">{story.meta.title}</span>\n        <span className=\"sg-bg\">{node.bg}</span>\n      </header>\n\n      {Hud ? <Hud vars={state.vars} variables={story.variables} characters={story.characters} /> : null}\n\n      <main className=\"sg-stage\" onClick={() => !allShown && setLineIndex(lineIndex + 1)}>\n        {speaker ? (\n          <div className=\"sg-portrait\" style={{ borderColor: speaker.color }}>\n            <span className=\"sg-avatar\">{speaker.avatar}</span>\n            <span className=\"sg-name\" style={{ color: speaker.color }}>{speaker.name}</span>\n          </div>\n        ) : null}\n        <p className={speaker ? \"sg-line\" : \"sg-line sg-narration\"} key={state.nodeId + \":\" + lineIndex}>\n          {line.text}\n        </p>\n        {!allShown ? <span className=\"sg-hint\">点击继续 ▸</span> : null}\n      </main>\n\n      {allShown && node.type === \"scene\" ? (\n        <nav className=\"sg-choices\">\n          {availableChoices(story, state).map(({ choice, index }) => (\n            <button key={index} className=\"sg-choice\" onClick={() => choose(index)}>\n              {choice.text}\n            </button>\n          ))}\n        </nav>\n      ) : null}\n\n      {allShown && node.type === \"ending\" ? (\n        <section className=\"sg-ending\">\n          <h2>结局：{node.title}</h2>\n          <p className=\"sg-muted\">\n            已解锁结局 {endings.length} / {endingNodes.length}\n          </p>\n          <ul className=\"sg-gallery\">\n            {endingNodes.map((e) => (\n              <li key={e.id} className={endings.includes(e.id) ? \"sg-unlocked\" : \"sg-locked\"}>\n                {endings.includes(e.id) ? e.title : \"？？？\"}\n              </li>\n            ))}\n          </ul>\n          <button className=\"sg-choice\" onClick={restart}>\n            重新开始\n          </button>\n        </section>\n      ) : null}\n    </div>\n  );\n}\n",
  "/engine/core.js": "// Story engine core — pure functions, no React, no DOM.\n// The same file runs inside the generated game (Sandpack) and on the server\n// (validator / auto-playtest), so simulation and real play always agree.\n\nexport function indexNodes(story) {\n  const map = {};\n  for (const node of story.nodes) map[node.id] = node;\n  return map;\n}\n\nexport function clampVar(def, value) {\n  return Math.max(def.min, Math.min(def.max, value));\n}\n\nexport function initState(story) {\n  const vars = {};\n  for (const v of story.variables) vars[v.id] = clampVar(v, v.init);\n  const start = indexNodes(story)[story.meta.start];\n  return {\n    nodeId: story.meta.start,\n    vars,\n    history: [story.meta.start],\n    ended: Boolean(start && start.type === \"ending\"),\n  };\n}\n\nexport function evalCondition(condition, vars) {\n  if (!condition) return true;\n  const value = vars[condition.var] ?? 0;\n  if (condition.op === \">=\") return value >= condition.value;\n  if (condition.op === \"<=\") return value <= condition.value;\n  if (condition.op === \"==\") return value === condition.value;\n  return false;\n}\n\n/** Choices the player can see right now, with their original index. */\nexport function availableChoices(story, state) {\n  const node = indexNodes(story)[state.nodeId];\n  if (!node || node.type !== \"scene\") return [];\n  return node.choices\n    .map((choice, index) => ({ choice, index }))\n    .filter(({ choice }) => evalCondition(choice.condition, state.vars));\n}\n\nexport function applyEffects(story, vars, effects) {\n  const defs = {};\n  for (const v of story.variables) defs[v.id] = v;\n  const out = { ...vars };\n  for (const e of effects || []) {\n    const def = defs[e.var];\n    if (!def) continue;\n    const next = e.op === \"set\" ? e.value : (out[e.var] ?? 0) + e.value;\n    out[e.var] = clampVar(def, next);\n  }\n  return out;\n}\n\n/** Take choice `choiceIndex` (index into node.choices). Throws if not allowed. */\nexport function step(story, state, choiceIndex) {\n  if (state.ended) throw new Error(\"game already ended\");\n  const nodes = indexNodes(story);\n  const node = nodes[state.nodeId];\n  if (!node || node.type !== \"scene\") throw new Error(`no scene at ${state.nodeId}`);\n  const choice = node.choices[choiceIndex];\n  if (!choice) throw new Error(`no choice ${choiceIndex} at ${state.nodeId}`);\n  if (!evalCondition(choice.condition, state.vars)) throw new Error(`choice ${choiceIndex} is locked`);\n  const next = nodes[choice.next];\n  if (!next) throw new Error(`missing node ${choice.next}`);\n  return {\n    nodeId: next.id,\n    vars: applyEffects(story, state.vars, choice.effects),\n    history: [...state.history, next.id],\n    ended: next.type === \"ending\",\n  };\n}\n",
